    r2: ['\\langle R^{2}\\rangle=C_\\infty Nb^{2},\\qquad R_g^{2}=\\tfrac16\\langle R^{2}\\rangle,\\qquad R\\propto N^{\\nu}\\ \\ (\\nu\\approx0.588\\ \\text{good solvent})', true],
    fh: ['\\frac{\\Delta G_{\\text{mix}}}{kT}=\\frac{\\phi}{N}\\ln\\phi+(1-\\phi)\\ln(1-\\phi)+\\chi\\phi(1-\\phi),\\qquad \\chi_c=\\tfrac12\\big(1+N^{-1/2}\\big)^{2}', true],
    wlf: ['\\lg a_T=-\\frac{C_1(T-T_g)}{C_2+T-T_g},\\qquad C_1\\approx17.4,\\ C_2\\approx51.6\\ \\mathrm K', true],
