      site: [['spectra/index.html', ['谱图馆 · 凝胶色谱和光散射', 'Spectra Hall · GPC and light scattering']], ['chemistry/analytical/index.html#c-separations', ['04 分析化学 · 分离', '04 Analytical · separations']]],
      refs: ['staudinger1920'],
